/**
 * Writes supabase/seed.sql from the sample shipments, so the database and the
 * offline fallback always hold exactly the same data.
 * Run: npm run db:seed-sql
 */
import { writeFileSync } from "node:fs";
import { SAMPLE_SHIPMENTS } from "../src/lib/shipments/sample-data.ts";

const q = (v: string) => `'${v.replaceAll("'", "''")}'`;

function offsetMinutes(iso: string): number {
  const m = /([+-])(\d{2}):(\d{2})$/.exec(iso);
  if (!m) return 0;
  const mins = Number(m[2]) * 60 + Number(m[3]);
  return m[1] === "-" ? -mins : mins;
}

const lines: string[] = [
  "-- Generated by scripts/generate-seed.ts. Do not edit by hand.",
  "-- Invented sample shipments: no real customers or tracking numbers.",
  "",
  "begin;",
  "",
];

for (const s of SAMPLE_SHIPMENTS) {
  lines.push(
    `with s as (`,
    `  insert into public.shipments (tracking_number, origin_city, origin_country, origin_hub, destination_city, destination_country, destination_hub, service, carrier, weight_kg, pieces, contents, estimated_delivery)`,
    `  values (${[
      s.trackingNumber,
      s.origin.city,
      s.origin.country,
      s.origin.hub,
      s.destination.city,
      s.destination.country,
      s.destination.hub,
      s.service,
      s.carrier,
    ]
      .map(q)
      .join(
        ", ",
      )}, ${s.weightKg}, ${s.pieces}, ${q(s.contents)}, ${q(s.estimatedDelivery)})`,
    `  on conflict (tracking_number) do nothing`,
    `  returning id`,
    `)`,
    `insert into public.tracking_events (shipment_id, stage, occurred_at, local_offset_minutes, location, note)`,
    `select s.id, e.stage::public.shipment_stage, e.occurred_at::timestamptz, e.offset_minutes, e.location, e.note`,
    `from s cross join (values`,
    s.events
      .map(
        (e) =>
          `  (${q(e.stage)}, ${q(e.at)}, ${offsetMinutes(e.at)}, ${q(e.location)}, ${q(e.note)})`,
      )
      .join(",\n"),
    `) as e(stage, occurred_at, offset_minutes, location, note);`,
    "",
  );
}

lines.push("commit;", "");
writeFileSync(new URL("../supabase/seed.sql", import.meta.url), lines.join("\n"));
console.log(`Wrote seed for ${SAMPLE_SHIPMENTS.length} shipments.`);
